import{_ as e}from"./chunks/4f0345d520b09559-20261015000320-h7od16n.DYEN10kg.js";import{_ as a,o as d,c as o,a2 as l}from"./chunks/framework.CG3qCjiJ.js";const r="/entismax/v5/assets/eb588f40b18d54fd-20261015000320-p5q20r4.CyBSWkvH.png",m=JSON.parse('{"title":"按表达式转换功能说明","description":"","frontmatter":{"title":"按表达式转换功能说明","date":"2026-10-14T16:03:20.000Z","lastmod":"2026-11-24T18:47:00.000Z"},"headers":[],"relativePath":"guide/1264.md","filePath":"guide/帮助文档/新功能说明/2026/按表达式转换功能说明.md"}'),i={name:"guide/1264.md"};function c(h,t,n,s,u,_){return d(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="按表达式转换功能说明" tabindex="-1">按表达式转换功能说明 <a class="header-anchor" href="#按表达式转换功能说明" aria-label="Permalink to &quot;按表达式转换功能说明&quot;">​</a></h1><h1 id="按表达式转换-―-使用说明" tabindex="-1">按表达式转换 ― 使用说明 <a class="header-anchor" href="#按表达式转换-―-使用说明" aria-label="Permalink to &quot;按表达式转换 ― 使用说明&quot;">​</a></h1><h2 id="功能简介" tabindex="-1">功能简介 <a class="header-anchor" href="#功能简介" aria-label="Permalink to &quot;功能简介&quot;">​</a></h2><p><strong>按表达式转换</strong>用于在读取仪表数据时，按您编写的公式对读数进行计算，得到最终显示值。</p><p>常见用途：</p><ul><li>读数放大或缩小，例如：​<code>value * 10</code></li><li>加上或减去固定数值，例如：​<code>value + 273.15</code></li><li>单位换算，例如：​<code>(value - 32) * 5 / 9</code></li><li>负值归零等简单处理</li></ul><blockquote><p><strong>说明：</strong> 本功能用于<strong>算出新的读数</strong>。若只需判断读数是否满足条件、决定是否忽略，请使用 <strong>「按表达式忽略」</strong> ，两者互不影响。</p></blockquote><hr><h2 id="如何配置" tabindex="-1">如何配置 <a class="header-anchor" href="#如何配置" aria-label="Permalink to &quot;如何配置&quot;">​</a></h2><ol><li>打开 <strong>储罐 / 仪表配置</strong>。</li><li>进入该仪表的配置页，当前支持 <em>Modbus</em> 和 <em>GPU</em> 协议。</li><li>在列表中找到要设置的数据项（如液位、温度等）。</li><li>在 <strong>单位转换</strong> 下拉框中选择 <strong>「按表达式转换」</strong> 。</li><li>在弹出的对话框中填写表达式，点击 <strong>确定</strong> 保存。</li></ol><p><img src="'+r+'" alt=""></p><p><img src="'+e+'" alt=""></p><hr><h2 id="如何编写表达式" tabindex="-1">如何编写表达式 <a class="header-anchor" href="#如何编写表达式" aria-label="Permalink to &quot;如何编写表达式&quot;">​</a></h2><h3 id="表达式规则" tabindex="-1">表达式规则 <a class="header-anchor" href="#表达式规则" aria-label="Permalink to &quot;表达式规则&quot;">​</a></h3><ul><li>支持基本算术运算：​<code>+</code>​、​<code>-</code>​、​<code>*</code>​、​<code>/</code>​、​<code>IIF(条件, 结果1, 结果2)</code>（条件判断函数）</li><li>小数点请使用​<code>.</code>（英文句号）</li><li>每个数据项可单独配置一条表达式</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p>读数为负时显示0，否则保持原值：<br> ​<code>IIF(value &lt; 0, 0, value)</code></p><p>注意事项：</p><ol><li><code>value</code>是已完成偏移、精度等常规处理之后的读数，不是寄存器原始值。</li><li>本功能仅影响读取显示，不影响写入。</li><li>请避免除以0等会导致计算失败的写法。</li><li>仅适合简单算术运算，不支持复杂函数或文字处理。</li></ol><hr><h2 id="常用示例" tabindex="-1">常用示例 <a class="header-anchor" href="#常用示例" aria-label="Permalink to &quot;常用示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>表达式</th><th>说明</th></tr></thead><tbody><tr><td>放大10倍</td><td><code>value * 10</code></td><td>12.5 → 125</td></tr><tr><td>加固定值</td><td><code>value + 273.15</code></td><td>25 → 298.15</td></tr><tr><td>华氏度转摄氏度</td><td><code>(value - 32) * 5 / 9</code></td><td>212 → 100</td></tr><tr><td>负值归零</td><td><code>IIF(value &lt; 0, 0, value)</code></td><td>-3 → 0，5 → 5</td></tr><tr><td>缩放并加偏移</td><td><code>value * 0.1 + 2.5</code></td><td>100 → 12.5</td></tr></tbody></table><hr><p>调试注意：<br> 检查表达式时注意运算符（​<code>&gt;</code>​、​<code>&lt;</code>​等）、括号是否配对、是否使用了不支持的符号；可先用​<code>value * 1</code>等简单表达式测试功能。</p><hr><h2 id="修订记录" tabindex="-1">修订记录 <a class="header-anchor" href="#修订记录" aria-label="Permalink to &quot;修订记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>1.0</td><td>2026-07-02</td><td>初版</td></tr></tbody></table>',28)])])}const g=a(i,[["render",c]]);export{m as __pageData,g as default};
